impl Opcode {
    pub fn mnemonic(self) -> &'static str {
        MNEMONICS[self as usize]
    }

    pub fn from_index(i: usize) -> Option<Opcode> {
        OPCODES.get(i).copied()
    }
}

/// The single slot of a format_32 instruction, from the 32-bit instruction word.
#[inline]
pub fn slot_format_32(insn: u32) -> u32 {
    let mut s = (insn & 0xff0) >> 4;
    s = (s & !0xf00) | (((insn & 0xf00000) >> 20) << 8);
    s = (s & !0xf000) | (((insn & 0xf000) >> 12) << 12);
    s = (s & !0x10000) | ((insn & 0x1) << 16);
    s = (s & !0x1e0000) | (((insn & 0xf0000) >> 16) << 17);
    s = (s & !0x1fe00000) | (((insn & 0xff000000) >> 24) << 21);
    s
}

